<?php
if($page==='admin-users'){
  require_admin();$list=$pdo->query("SELECT u.*,COUNT(b.id) booking_count,COALESCE(SUM(CASE WHEN b.payment_status='paid' THEN b.total_amount ELSE 0 END),0) paid_total FROM users u LEFT JOIN bookings b ON b.user_id=u.id GROUP BY u.id ORDER BY u.created_at DESC LIMIT 300")->fetchAll();layout_start('Manage users',true);?>
  <section class="container section"><div class="section-head"><div><span class="eyebrow">Accounts</span><h1>Users</h1></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Bookings</th><th>Paid total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($list as $u):?><tr><td><strong><?=e($u['name'])?></strong><br><small><?=e($u['email'])?></small></td><td><?=e($u['role'])?></td><td><?=(int)$u['booking_count']?></td><td><?=e(money((float)$u['paid_total']))?></td><td><span class="status status-<?=e($u['status'])?>"><?=e($u['status'])?></span></td><td><?php if($u['role']==='customer'):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="admin-user-status"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><input type="hidden" name="status" value="<?=$u['status']==='active'?'disabled':'active'?>"><button class="btn btn-small <?=$u['status']==='active'?'btn-danger':'btn-light'?>" type="submit"><?=$u['status']==='active'?'Disable':'Enable'?></button></form><?php else:?><small>Administrator</small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></section>
  <?php layout_end();exit;
